using System;
using System.Collections.Generic;
using Framework.Parameters;
using Game.AI.Parameters;
using UnityEngine;

#if UNITY_EDITOR
using UnityEditor;
#endif

namespace Game.Tests
{
    /// <summary>
    /// 敵の共通パラメーターとプロファイルを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyParameterTest : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 40;

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

#if UNITY_EDITOR
            try
            {
                TestDefinitions();
                TestDefaultParameters();
                TestProfile();
                TestRuntimeChanges();
                TestIndependence();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【MazeEnemyParameter テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
#else
            Debug.LogWarning(
                "このテストはUnity Editor専用です。",
                this);
#endif
        }

        /// <summary>
        /// 共通パラメーター定義を検証する。
        /// </summary>
        private void TestDefinitions()
        {
            bool countPassed =
                MazeEnemyParameterCatalog.Count == 16;
            Debug.Assert(countPassed, "定義件数", this);
            Check(countPassed, "定義件数");

            bool enumPassed =
                Enum.GetValues(
                    typeof(MazeEnemyParameter)).Length == 17;
            Debug.Assert(enumPassed, "識別子件数", this);
            Check(enumPassed, "識別子件数");

            bool nonePassed =
                !MazeEnemyParameterCatalog.Contains(
                    MazeEnemyParameter.None);
            Debug.Assert(nonePassed, "Noneの定義除外", this);
            Check(nonePassed, "Noneの定義除外");

            var ids = new HashSet<MazeEnemyParameter>();

            bool uniquePassed = true;

            foreach (var definition in
                MazeEnemyParameterCatalog.Definitions)
            {
                uniquePassed &= ids.Add(definition.Id);
            }

            Debug.Assert(uniquePassed, "識別子の一意性", this);
            Check(uniquePassed, "識別子の一意性");

            bool coveragePassed = true;

            foreach (MazeEnemyParameter id in
                Enum.GetValues(typeof(MazeEnemyParameter)))
            {
                if (id != MazeEnemyParameter.None)
                {
                    coveragePassed &=
                        MazeEnemyParameterCatalog.Contains(id);
                }
            }

            Debug.Assert(coveragePassed, "全識別子の定義確認", this);
            Check(coveragePassed, "全識別子の定義確認");

            bool rangePassed = true;

            foreach (var definition in
                MazeEnemyParameterCatalog.Definitions)
            {
                rangePassed &= definition.IsInRange(
                    definition.DefaultValue);
            }

            Debug.Assert(rangePassed, "全初期値の範囲確認", this);
            Check(rangePassed, "全初期値の範囲確認");

            bool missingPassed =
                !MazeEnemyParameterCatalog.TryGetDefinition(
                    MazeEnemyParameter.None,
                    out var missing) &&
                missing == null;
            Debug.Assert(missingPassed, "未定義識別子の取得失敗", this);
            Check(missingPassed, "未定義識別子の取得失敗");

            bool exceptionPassed =
                Throws<KeyNotFoundException>(() =>
                    MazeEnemyParameterCatalog.GetDefinition(
                        (MazeEnemyParameter)9999));
            Debug.Assert(exceptionPassed, "不正識別子の例外処理", this);
            Check(exceptionPassed, "不正識別子の例外処理");
        }

        /// <summary>
        /// 標準パラメーターセットを検証する。
        /// </summary>
        private void TestDefaultParameters()
        {
            using (var parameters =
                MazeEnemyParameterCatalog.CreateParameterSet())
            {
                bool countPassed = parameters.Count == 16;
                Debug.Assert(countPassed, "全パラメーター登録", this);
                Check(countPassed, "全パラメーター登録");

                bool speedPassed = NearlyEqual(
                    parameters.GetValue(
                        MazeEnemyParameter.MoveSpeed), 3.5f);
                Debug.Assert(speedPassed, "基本移動速度", this);
                Check(speedPassed, "基本移動速度");

                bool chasePassed = NearlyEqual(
                    parameters.GetValue(
                        MazeEnemyParameter.ChaseSpeedMultiplier),
                    1.15f);
                Debug.Assert(chasePassed, "追跡速度倍率", this);
                Check(chasePassed, "追跡速度倍率");

                bool escapePassed = NearlyEqual(
                    parameters.GetValue(
                        MazeEnemyParameter.EscapeSpeedMultiplier),
                    1.3f);
                Debug.Assert(escapePassed, "逃走速度倍率", this);
                Check(escapePassed, "逃走速度倍率");

                bool detectionPassed = NearlyEqual(
                    parameters.GetValue(
                        MazeEnemyParameter.DetectionRange), 6f);
                Debug.Assert(detectionPassed, "認識距離", this);
                Check(detectionPassed, "認識距離");

                bool memoryPassed = NearlyEqual(
                    parameters.GetValue(
                        MazeEnemyParameter.MemoryDuration), 5f);
                Debug.Assert(memoryPassed, "記憶保持時間", this);
                Check(memoryPassed, "記憶保持時間");

                bool defaultsPassed = true;

                foreach (var definition in
                    MazeEnemyParameterCatalog.Definitions)
                {
                    defaultsPassed &= NearlyEqual(
                        parameters.GetValue(definition.Id),
                        definition.DefaultValue);
                }

                Debug.Assert(defaultsPassed, "全標準値の一致", this);
                Check(defaultsPassed, "全標準値の一致");

                bool sharedPassed = ReferenceEquals(
                    parameters.GetParameter(
                        MazeEnemyParameter.MoveSpeed).Definition,
                    MazeEnemyParameterCatalog.GetDefinition(
                        MazeEnemyParameter.MoveSpeed));
                Debug.Assert(sharedPassed, "共通定義の共有", this);
                Check(sharedPassed, "共通定義の共有");
            }
        }

#if UNITY_EDITOR
        /// <summary>
        /// 敵プロファイルの初期値と補正を検証する。
        /// </summary>
        private void TestProfile()
        {
            var profile =
                ScriptableObject.CreateInstance<MazeEnemyProfile>();

            try
            {
                bool namePassed =
                    profile.DisplayName == "標準型";
                Debug.Assert(namePassed, "プロファイル表示名", this);
                Check(namePassed, "プロファイル表示名");

                bool defaultsPassed = true;

                foreach (var definition in
                    MazeEnemyParameterCatalog.Definitions)
                {
                    defaultsPassed &= NearlyEqual(
                        profile.GetInitialValue(definition.Id),
                        definition.DefaultValue);
                }

                Debug.Assert(defaultsPassed, "プロファイル標準値", this);
                Check(defaultsPassed, "プロファイル標準値");

                SetProfileFloat(profile, "aggression", 0.95f);

                bool aggressionPassed = NearlyEqual(
                    profile.GetInitialValue(
                        MazeEnemyParameter.Aggression), 0.95f);
                Debug.Assert(aggressionPassed, "性格設定の反映", this);
                Check(aggressionPassed, "性格設定の反映");

                SetProfileFloat(profile, "moveSpeed", 4.2f);

                bool speedPassed = NearlyEqual(
                    profile.GetInitialValue(
                        MazeEnemyParameter.MoveSpeed), 4.2f);
                Debug.Assert(speedPassed, "能力設定の反映", this);
                Check(speedPassed, "能力設定の反映");

                SetProfileFloat(profile, "caution", 2f);

                bool maxPassed = NearlyEqual(
                    profile.GetInitialValue(
                        MazeEnemyParameter.Caution), 1f);
                Debug.Assert(maxPassed, "上限値の補正", this);
                Check(maxPassed, "上限値の補正");

                SetProfileFloat(profile, "exploration", -1f);

                bool minPassed = NearlyEqual(
                    profile.GetInitialValue(
                        MazeEnemyParameter.Exploration), 0f);
                Debug.Assert(minPassed, "下限値の補正", this);
                Check(minPassed, "下限値の補正");

                using (var parameters =
                    profile.CreateParameterSet())
                {
                    bool initialPassed = NearlyEqual(
                        parameters.GetParameter(
                            MazeEnemyParameter.Aggression)
                            .InitialValue, 0.95f);
                    Debug.Assert(initialPassed, "固有初期値の登録", this);
                    Check(initialPassed, "固有初期値の登録");
                }

                bool invalidPassed =
                    Throws<KeyNotFoundException>(() =>
                        profile.GetInitialValue(
                            MazeEnemyParameter.None));
                Debug.Assert(invalidPassed, "不正プロファイル識別子", this);
                Check(invalidPassed, "不正プロファイル識別子");
            }
            finally
            {
                DestroyTestProfile(profile);
            }
        }
#endif

        /// <summary>
        /// 実行時パラメーターの変更と補正を検証する。
        /// </summary>
        private void TestRuntimeChanges()
        {
            using (var parameters =
                MazeEnemyParameterCatalog.CreateParameterSet())
            {
                var id = MazeEnemyParameter.MoveSpeed;

                parameters.SetBaseValue(id, 4f);

                bool basePassed = NearlyEqual(
                    parameters.GetValue(id), 4f);
                Debug.Assert(basePassed, "基本値変更", this);
                Check(basePassed, "基本値変更");

                var additive =
                    ParameterModifier.CreateAdditive(1f);

                parameters.TryAddModifier(id, additive);

                bool additivePassed = NearlyEqual(
                    parameters.GetValue(id), 5f);
                Debug.Assert(additivePassed, "加算補正", this);
                Check(additivePassed, "加算補正");

                var multiplier =
                    ParameterModifier.CreateMultiplicative(2f);

                parameters.TryAddModifier(id, multiplier);

                bool multiplierPassed = NearlyEqual(
                    parameters.GetValue(id), 10f);
                Debug.Assert(multiplierPassed, "乗算補正", this);
                Check(multiplierPassed, "乗算補正");

                parameters.SetBaseValue(id, 10f);

                bool clampPassed = NearlyEqual(
                    parameters.GetValue(id), 12f);
                Debug.Assert(clampPassed, "最終値の上限補正", this);
                Check(clampPassed, "最終値の上限補正");

                parameters.TryRemoveModifier(id, multiplier.Id);

                bool removePassed = NearlyEqual(
                    parameters.GetValue(id), 11f);
                Debug.Assert(removePassed, "補正の解除", this);
                Check(removePassed, "補正の解除");

                parameters.ClearModifiers();

                bool clearPassed = NearlyEqual(
                    parameters.GetValue(id), 10f);
                Debug.Assert(clearPassed, "全補正の解除", this);
                Check(clearPassed, "全補正の解除");

                parameters.SetBaseValue(
                    MazeEnemyParameter.Aggression, 2f);

                bool personalityPassed = NearlyEqual(
                    parameters.GetValue(
                        MazeEnemyParameter.Aggression), 1f);
                Debug.Assert(personalityPassed, "性格値の範囲補正", this);
                Check(personalityPassed, "性格値の範囲補正");

                parameters.SetBaseValue(
                    MazeEnemyParameter.Caution, 1f);

                bool coexistPassed =
                    NearlyEqual(
                        parameters.GetValue(
                            MazeEnemyParameter.Aggression), 1f) &&
                    NearlyEqual(
                        parameters.GetValue(
                            MazeEnemyParameter.Caution), 1f);
                Debug.Assert(coexistPassed, "攻撃性と警戒心の独立性", this);
                Check(coexistPassed, "攻撃性と警戒心の独立性");
            }
        }

#if UNITY_EDITOR
        /// <summary>
        /// エージェント間の独立性とリセットを検証する。
        /// </summary>
        private void TestIndependence()
        {
            var profile =
                ScriptableObject.CreateInstance<MazeEnemyProfile>();

            try
            {
                SetProfileFloat(profile, "aggression", 0.9f);
                SetProfileFloat(profile, "moveSpeed", 4f);

                using (var first = profile.CreateParameterSet())
                using (var second = profile.CreateParameterSet())
                {
                    var id = MazeEnemyParameter.Aggression;

                    bool instancePassed =
                        !ReferenceEquals(
                            first.GetParameter(id),
                            second.GetParameter(id));
                    Debug.Assert(instancePassed, "実行時インスタンスの独立", this);
                    Check(instancePassed, "実行時インスタンスの独立");

                    first.SetBaseValue(id, 0.2f);

                    bool valuePassed = NearlyEqual(
                        second.GetValue(id), 0.9f);
                    Debug.Assert(valuePassed, "他個体への変更影響防止", this);
                    Check(valuePassed, "他個体への変更影響防止");

                    first.TryAddModifier(
                        id,
                        ParameterModifier.CreateAdditive(0.3f));

                    bool modifierPassed =
                        second.GetParameter(id).ModifierCount == 0;
                    Debug.Assert(modifierPassed, "補正状態の独立", this);
                    Check(modifierPassed, "補正状態の独立");

                    bool profilePassed = NearlyEqual(
                        profile.GetInitialValue(id), 0.9f);
                    Debug.Assert(profilePassed, "共有プロファイルの保護", this);
                    Check(profilePassed, "共有プロファイルの保護");

                    first.ResetAll();

                    bool resetPassed = NearlyEqual(
                        first.GetValue(id), 0.9f);
                    Debug.Assert(resetPassed, "固有初期値への復帰", this);
                    Check(resetPassed, "固有初期値への復帰");

                    bool resetModifierPassed =
                        first.GetParameter(id).ModifierCount == 0;
                    Debug.Assert(resetModifierPassed, "リセット時の補正解除", this);
                    Check(resetModifierPassed, "リセット時の補正解除");

                    SetProfileFloat(profile, "aggression", 0.6f);

                    using (var third = profile.CreateParameterSet())
                    {
                        bool snapshotPassed =
                            NearlyEqual(first.GetValue(id), 0.9f) &&
                            NearlyEqual(third.GetValue(id), 0.6f);
                        Debug.Assert(snapshotPassed, "生成後の設定独立性", this);
                        Check(snapshotPassed, "生成後の設定独立性");
                    }

                    first.Dispose();

                    bool disposePassed =
                        first.IsDisposed &&
                        !second.IsDisposed &&
                        NearlyEqual(second.GetValue(id), 0.9f);
                    Debug.Assert(disposePassed, "個別解放の独立性", this);
                    Check(disposePassed, "個別解放の独立性");
                }
            }
            finally
            {
                DestroyTestProfile(profile);
            }
        }

        /// <summary>
        /// テスト用プロファイルのシリアライズ値を変更する。
        /// </summary>
        /// <param name="profile">変更対象のプロファイル</param>
        /// <param name="fieldName">対象フィールド名</param>
        /// <param name="value">設定する数値</param>
        private void SetProfileFloat(
            MazeEnemyProfile profile,
            string fieldName,
            float value)
        {
            var serializedObject =
                new SerializedObject(profile);

            serializedObject.Update();

            var property =
                serializedObject.FindProperty(fieldName);

            if (property == null)
            {
                throw new InvalidOperationException(
                    $"フィールドが見つかりません：{fieldName}");
            }

            property.floatValue = value;

            serializedObject.ApplyModifiedPropertiesWithoutUndo();
        }

        /// <summary>
        /// 一時生成したテスト用プロファイルを破棄する。
        /// </summary>
        /// <param name="profile">破棄対象</param>
        private void DestroyTestProfile(MazeEnemyProfile profile)
        {
            if (profile == null)
            {
                return;
            }

            if (Application.isPlaying)
            {
                Destroy(profile);
            }
            else
            {
                DestroyImmediate(profile);
            }
        }
#endif

        /// <summary>
        /// 浮動小数点数を許容誤差付きで比較する。
        /// </summary>
        /// <param name="first">比較する数値</param>
        /// <param name="second">比較対象の数値</param>
        /// <returns>十分に近い場合はtrue</returns>
        private bool NearlyEqual(float first, float second)
        {
            return Mathf.Abs(first - second) <= 0.0001f;
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか確認する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
